// Phone wallet route sheet. MetaMask Mobile's WalletConnect can stop answering
// entirely (2026-10-16: it opened with no prompt for this site AND Uniswap,
// for transactions and brand-new pairings alike), while MetaMask's own phone
// link (MetaMask Connect, what Uniswap's "MetaMask" button uses) and its
// in-app browser both keep working. The sheet offers those routes before
// connecting and again when a WalletConnect wallet stops answering.

const SHEET_ID = 'wallet-route-sheet';

/**
 * A link that opens this page in MetaMask's in-app browser. Android gets an
 * intent URL naming the app package: Chrome sent the universal link to the
 * Play Store listing instead (2026-10-16), whose OPEN button only launches the
 * wallet home and drops the page. iOS keeps the universal link.
 */
export function metamaskDappLink(loc = globalThis.location, userAgent = globalThis.navigator?.userAgent) {
  const host = String(loc?.host || '');
  const params = new URLSearchParams(String(loc?.search || ''));
  params.delete('wcdebug');
  const query = params.toString();
  const target = `${host}${loc?.pathname || '/'}${query ? `?${query}` : ''}`;
  if (/Android/i.test(String(userAgent || ''))) {
    return `intent://dapp/${target}#Intent;scheme=metamask;package=io.metamask;end`;
  }
  return `https://metamask.app.link/dapp/${target}`;
}

export function openInMetaMask() {
  try { globalThis.location.assign(metamaskDappLink()); } catch (_e) { /* headless */ }
}

const COPY = {
  connect: {
    title: 'CONNECT ON THIS PHONE',
    body: 'MetaMask connects directly. Other wallets use WalletConnect.',
    primary: 'METAMASK',
    secondary: 'OTHER WALLET (WALLETCONNECT)',
    secondaryRoute: 'walletconnect',
  },
  silent: {
    title: "YOUR WALLET DIDN'T ANSWER",
    body: 'Its WalletConnect link is not responding. MetaMask can connect directly instead.',
    primary: 'CONNECT METAMASK DIRECTLY',
    secondary: 'RECONNECT WALLETCONNECT',
    secondaryRoute: 'reconnect',
  },
};

/**
 * Show the route sheet. Resolves 'metamask-connect', the mode's secondary
 * route ('walletconnect' or 'reconnect'), 'metamask' (after starting the
 * navigation into MetaMask's browser), or null when the player closes it.
 */
export function chooseMobileWalletRoute(mode = 'connect') {
  const doc = globalThis.document;
  const copy = COPY[mode] || COPY.connect;
  if (!doc?.body) return Promise.resolve(copy.secondaryRoute);
  doc.getElementById(SHEET_ID)?.remove();
  return new Promise((resolve) => {
    const sheet = doc.createElement('div');
    sheet.id = SHEET_ID;
    sheet.className = 'wallet-route-sheet';
    sheet.setAttribute('role', 'dialog');
    sheet.setAttribute('aria-modal', 'true');
    sheet.setAttribute('aria-labelledby', `${SHEET_ID}-title`);
    sheet.innerHTML = `
      <button type="button" class="wallet-route-sheet__backdrop" data-route="close" aria-label="Close"></button>
      <section class="wallet-route-sheet__card">
        <strong id="${SHEET_ID}-title"></strong>
        <p></p>
        <button type="button" class="wallet-route-sheet__primary" data-route="metamask-connect"></button>
        <button type="button" class="wallet-route-sheet__secondary" data-route="${copy.secondaryRoute}"></button>
        <button type="button" class="wallet-route-sheet__link" data-route="metamask">OPEN THIS SITE IN METAMASK'S BROWSER</button>
        <button type="button" class="wallet-route-sheet__close" data-route="close">NOT NOW</button>
      </section>`;
    sheet.querySelector('strong').textContent = copy.title;
    sheet.querySelector('p').textContent = copy.body;
    sheet.querySelector('[data-route="metamask-connect"]').textContent = copy.primary;
    sheet.querySelector(`[data-route="${copy.secondaryRoute}"]`).textContent = copy.secondary;
    const finish = (route) => {
      sheet.remove();
      if (route === 'metamask') openInMetaMask();
      resolve(route === 'close' ? null : route);
    };
    sheet.addEventListener('click', (event) => {
      const route = event.target?.closest?.('[data-route]')?.dataset.route;
      if (route) finish(route);
    });
    sheet.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') finish('close');
    });
    doc.body.appendChild(sheet);
    try { sheet.querySelector('[data-route="metamask-connect"]').focus({ preventScroll: true }); } catch (_e) { /* headless */ }
  });
}
